/**
 * One progress event as recorded, discriminated by `type`. Every event names its `agent`, so a multi-agent run
 * stays readable in one stream, and carries `thread` (invocation identity) ONLY for a non-root run. The payload
 * fields below are per-variant and documented there because a recorded turn keeps them verbatim forever; a
 * consumer reads the variant list on `HarnessEventType` and treats an unknown `type` as data.
 */
export interface HarnessEvent {
    type: HarnessEventType;
    agent: string;
    model?: string;
    delta?: string;
    call?: HarnessToolCall;
    name?: string;
    callId?: string;
    content?: string;
    isError?: boolean;
    outcome?: unknown;
    ui?: ToolUiPanel[];
    media?: ToolMediaDescriptor[];
    durationMs?: number;
    pending?: HarnessPendingTool[];
    usage?: HarnessUsage;
    error?: HarnessErrorInfo;
    delayMs?: number;
    request?: HarnessActionRequest;
    answer?: unknown;
    branchId?: string;
    thread?: HarnessThread;
}

/**
 * A session metadata delta: status, queue depth, model map, and the last error - the fields a rail or a header
 * draws. No turns, threads, transcripts, events, or definition data, and `revision` always present so the frame
 * can be ordered against a read.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface SessionStatePatch {
    id: string;
    title?: string;
    status?: SessionStatus;
    queue_depth?: number;
    model?: string;
    agent_models?: {
      [key: string]: string;
      };
    last_error?: string;
    revision: number;
}

/**
 * The server's running token figures for a turn or for a session. Figures travel precomputed because the server
 * is the one that summed them from per-request `usage` events; a client never accumulates anything and
 * therefore can never double-count a replay.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface UsagePatch {
    turn_id?: string;
    usage?: HarnessUsage;
    latest_input?: number;
    cached_input?: number;
    revision: number;
}

/**
 * A transcript changed, stated as counts and a revision. Message bodies never ride the stream: an editor
 * re-pages, and a render path that is not showing this transcript ignores the frame entirely.
 * Closed object: the server sends no property outside this set (additionalProperties: false).
 */
export interface TranscriptSignal {
    thread_id: string;
    revision: number;
    message_count: number;
    transcript_state: "ok" | "unreadable";
}
